// Unicode algorithms for the String built-ins (ROADMAP Phase 9C): full case
// mapping (toUpperCase / toLowerCase with SpecialCasing and Final_Sigma) and
// the four normalization forms. VM-independent: they work on [UInt16].
//
// API:
//   jsStringToUpper(_ units: [UInt16]) -> [UInt16]
//   jsStringToLower(_ units: [UInt16]) -> [UInt16]
//   jsStringNormalize(_ units: [UInt16], _ form: JSNormForm) -> [UInt16]
//   jsIsWhiteSpaceOrLT(_ u: UInt16) -> Bool        (trim)
//
// The data is in jsstringtables.swift (generated by tools/gen_js_string_tables.py).
// Language-sensitive mappings (tr, az, lt) are not applied: toLocale*Case is
// the same as the plain forms.

enum JSNormForm { case nfc, nfd, nfkc, nfkd }

// MARK: Table access

@inline(__always) private func jsTabDigit(_ c: UInt8) -> UInt64 {
    if c >= 0x41 && c <= 0x5A { return UInt64(c - 0x41) }
    if c >= 0x61 && c <= 0x7A { return UInt64(c - 0x61 + 26) }
    if c >= 0x30 && c <= 0x39 { return UInt64(c - 0x30 + 52) }
    return c == 0x2B ? 62 : 63
}

/// A field of `width` base64 chars at char offset `at`.
@inline(__always) private func jsTabField(_ p: UnsafePointer<UInt8>, _ at: Int, _ width: Int) -> UInt64 {
    var v: UInt64 = 0
    var i = 0
    while i < width {
        v = (v << 6) | jsTabDigit(p[at + i])
        i += 1
    }
    return v
}

/// Binary search a table of `count` records of `rec` chars whose first
/// `keyWidth` chars are the key; returns the record index or -1.
private func jsTabFind(_ t: StaticString, _ count: Int, _ rec: Int, _ keyWidth: Int, _ key: UInt64) -> Int {
    let p = t.utf8Start
    var lo = 0, hi = count - 1
    while lo <= hi {
        let mid = (lo + hi) >> 1
        let k = jsTabField(p, mid * rec, keyWidth)
        if k == key { return mid }
        if k < key { lo = mid + 1 } else { hi = mid - 1 }
    }
    return -1
}

/// Is `c` inside one of the 7-char (first | last << 21) range records?
private func jsTabInRanges(_ t: StaticString, _ count: Int, _ c: UInt32) -> Bool {
    let p = t.utf8Start
    var lo = 0, hi = count - 1
    while lo <= hi {
        let mid = (lo + hi) >> 1
        let v = jsTabField(p, mid * 7, 7)
        let first = UInt32(truncatingIfNeeded: v & 0x1FFFFF), last = UInt32(truncatingIfNeeded: v >> 21)
        if c < first { hi = mid - 1 } else if c > last { lo = mid + 1 } else { return true }
    }
    return false
}

// MARK: Code point iteration

/// The code point at `i` and its length in units (lone surrogates as is).
@inline(__always) func jsCodePointAt(_ s: [UInt16], _ i: Int) -> (UInt32, Int) {
    let u = s[i]
    if u >= 0xD800 && u <= 0xDBFF && i + 1 < s.count {
        let v = s[i + 1]
        if v >= 0xDC00 && v <= 0xDFFF {
            return (0x10000 + ((UInt32(u) - 0xD800) << 10) + (UInt32(v) - 0xDC00), 2)
        }
    }
    return (UInt32(u), 1)
}

@inline(__always) func jsAppendCodePoint(_ out: inout [UInt16], _ c: UInt32) {
    if c < 0x10000 { out.append(UInt16(truncatingIfNeeded: c)); return }
    let v = c - 0x10000
    out.append(UInt16(truncatingIfNeeded: 0xD800 | (v >> 10)))
    out.append(UInt16(truncatingIfNeeded: 0xDC00 | (v & 0x3FF)))
}

// MARK: White space

/// WhiteSpace or LineTerminator (what trim removes).
func jsIsWhiteSpaceOrLT(_ u: UInt16) -> Bool {
    switch u {
    case 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20, 0xA0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF:
        return true
    default:
        return u >= 0x2000 && u <= 0x200A
    }
}

// MARK: Case mapping

func jsLowerSingle(_ c: UInt32) -> UInt32 {
    if c < 0x80 { return c >= 0x41 && c <= 0x5A ? c + 32 : c }
    let i = jsTabFind(jsCaseLower, jsCaseLowerCount, 8, 4, UInt64(c))
    if i < 0 { return c }
    return UInt32(truncatingIfNeeded: jsTabField(jsCaseLower.utf8Start, i * 8 + 4, 4))
}

private func jsUpperSingle(_ c: UInt32) -> UInt32 {
    let i = jsTabFind(jsCaseUpper, jsCaseUpperCount, 8, 4, UInt64(c))
    if i < 0 { return c }
    return UInt32(truncatingIfNeeded: jsTabField(jsCaseUpper.utf8Start, i * 8 + 4, 4))
}

private func jsIsCased(_ c: UInt32) -> Bool { jsTabInRanges(jsCasedRanges, jsCasedRangesCount, c) }
private func jsIsCaseIgnorable(_ c: UInt32) -> Bool {
    jsTabInRanges(jsCaseIgnorableRanges, jsCaseIgnorableRangesCount, c)
}

func jsStringToUpper(_ s: [UInt16]) -> [UInt16] {
    var out: [UInt16] = []
    out.reserveCapacity(s.count)
    var i = 0
    let n = s.count
    while i < n {
        let u = s[i]
        if u < 0x80 {
            out.append(u >= 0x61 && u <= 0x7A ? u - 32 : u)
            i += 1
            continue
        }
        let (c, len) = jsCodePointAt(s, i)
        i += len
        let m = jsTabFind(jsCaseUpperMulti, jsCaseUpperMultiCount, 17, 4, UInt64(c))
        if m >= 0 {
            let p = jsCaseUpperMulti.utf8Start
            let cnt = Int(jsTabField(p, m * 17 + 4, 1))
            var k = 0
            while k < cnt && k < 3 {
                jsAppendCodePoint(&out, UInt32(truncatingIfNeeded: jsTabField(p, m * 17 + 5 + k * 4, 4)))
                k += 1
            }
            continue
        }
        jsAppendCodePoint(&out, jsUpperSingle(c))
    }
    return out
}

func jsStringToLower(_ s: [UInt16]) -> [UInt16] {
    var out: [UInt16] = []
    out.reserveCapacity(s.count)
    var i = 0
    let n = s.count
    while i < n {
        let u = s[i]
        if u < 0x80 {
            out.append(u >= 0x41 && u <= 0x5A ? u + 32 : u)
            i += 1
            continue
        }
        let (c, len) = jsCodePointAt(s, i)
        if c == 0x130 {
            out.append(0x69)
            out.append(0x307)
        } else if c == 0x3A3 {
            out.append(jsFinalSigma(s, i) ? 0x3C2 : 0x3C3)
        } else {
            jsAppendCodePoint(&out, jsLowerSingle(c))
        }
        i += len
    }
    return out
}

/// Final_Sigma: preceded by a cased letter (skipping case-ignorables) and
/// not followed by one.
private func jsFinalSigma(_ s: [UInt16], _ at: Int) -> Bool {
    // Backward.
    var j = at
    var before = false
    while j > 0 {
        var c = UInt32(s[j - 1])
        var step = 1
        if c >= 0xDC00 && c <= 0xDFFF && j >= 2 {
            let h = UInt32(s[j - 2])
            if h >= 0xD800 && h <= 0xDBFF {
                c = 0x10000 + ((h - 0xD800) << 10) + (c - 0xDC00)
                step = 2
            }
        }
        if jsIsCaseIgnorable(c) { j -= step; continue }
        before = jsIsCased(c)
        break
    }
    if !before { return false }
    var k = at + 1
    while k < s.count {
        let (c, len) = jsCodePointAt(s, k)
        if jsIsCaseIgnorable(c) { k += len; continue }
        return !jsIsCased(c)
    }
    return true
}

// MARK: Normalization

private let jsHangulSBase: UInt32 = 0xAC00, jsHangulLBase: UInt32 = 0x1100, jsHangulVBase: UInt32 = 0x1161
private let jsHangulTBase: UInt32 = 0x11A7
private let jsHangulLCount: UInt32 = 19, jsHangulVCount: UInt32 = 21, jsHangulTCount: UInt32 = 28
private let jsHangulNCount: UInt32 = 21 * 28, jsHangulSCount: UInt32 = 19 * 21 * 28

func jsCombiningClass(_ c: UInt32) -> UInt8 {
    if c < 0x300 { return 0 }
    let p = jsNormCCC.utf8Start
    var lo = 0, hi = jsNormCCCCount - 1
    while lo <= hi {
        let mid = (lo + hi) >> 1
        let first = UInt32(truncatingIfNeeded: jsTabField(p, mid * 10, 4))
        let last = UInt32(truncatingIfNeeded: jsTabField(p, mid * 10 + 4, 4))
        if c < first { hi = mid - 1 } else if c > last { lo = mid + 1 } else {
            return UInt8(truncatingIfNeeded: jsTabField(p, mid * 10 + 8, 2))
        }
    }
    return 0
}

/// Append the full decomposition of `c` (canonical, or compatibility too).
private func jsDecompose(_ c: UInt32, compat: Bool, _ out: inout [UInt32]) {
    if c < 0xA0 { out.append(c); return }
    if c >= jsHangulSBase && c < jsHangulSBase + jsHangulSCount {
        let si = c - jsHangulSBase
        out.append(jsHangulLBase + si / jsHangulNCount)
        out.append(jsHangulVBase + (si % jsHangulNCount) / jsHangulTCount)
        let t = si % jsHangulTCount
        if t != 0 { out.append(jsHangulTBase + t) }
        return
    }
    if compat {
        let i = jsTabFind(jsNormNFKD, jsNormNFKDCount, 9, 4, UInt64(c))
        if i >= 0 {
            let p = jsNormNFKD.utf8Start
            let off = Int(jsTabField(p, i * 9 + 4, 4)), len = Int(jsTabField(p, i * 9 + 8, 1))
            let pp = jsNormNFKDPool.utf8Start
            var k = 0
            while k < len { out.append(UInt32(truncatingIfNeeded: jsTabField(pp, (off + k) * 4, 4))); k += 1 }
            return
        }
    }
    let i = jsTabFind(jsNormNFD, jsNormNFDCount, 9, 4, UInt64(c))
    if i >= 0 {
        let p = jsNormNFD.utf8Start
        let off = Int(jsTabField(p, i * 9 + 4, 4)), len = Int(jsTabField(p, i * 9 + 8, 1))
        let pp = jsNormNFDPool.utf8Start
        var k = 0
        while k < len { out.append(UInt32(truncatingIfNeeded: jsTabField(pp, (off + k) * 4, 4))); k += 1 }
        return
    }
    out.append(c)
}

private func jsComposePair(_ a: UInt32, _ b: UInt32) -> UInt32? {
    if a >= jsHangulLBase && a < jsHangulLBase + jsHangulLCount && b >= jsHangulVBase && b < jsHangulVBase + jsHangulVCount {
        return jsHangulSBase + ((a - jsHangulLBase) * jsHangulVCount + (b - jsHangulVBase)) * jsHangulTCount
    }
    if a >= jsHangulSBase && a < jsHangulSBase + jsHangulSCount && (a - jsHangulSBase) % jsHangulTCount == 0
        && b > jsHangulTBase && b < jsHangulTBase + jsHangulTCount {
        return a + (b - jsHangulTBase)
    }
    let p = jsNormComp.utf8Start
    let key = (UInt64(a) << 21) | UInt64(b)
    var lo = 0, hi = jsNormCompCount - 1
    while lo <= hi {
        let mid = (lo + hi) >> 1
        let k = (jsTabField(p, mid * 12, 4) << 21) | jsTabField(p, mid * 12 + 4, 4)
        if k == key { return UInt32(truncatingIfNeeded: jsTabField(p, mid * 12 + 8, 4)) }
        if k < key { lo = mid + 1 } else { hi = mid - 1 }
    }
    return nil
}

func jsStringNormalize(_ s: [UInt16], _ form: JSNormForm) -> [UInt16] {
    let compat = form == .nfkd || form == .nfkc
    let limit: UInt16 = compat ? 0xA0 : 0xC0
    var ascii = true
    for u in s where u >= limit { ascii = false; break }
    if ascii { return s }
    // Decompose.
    var cps: [UInt32] = []
    cps.reserveCapacity(s.count + 8)
    var i = 0
    while i < s.count {
        let (c, len) = jsCodePointAt(s, i)
        i += len
        jsDecompose(c, compat: compat, &cps)
    }
    // Canonical ordering: stable insertion sort of each run of non-starters.
    var classes = [UInt8](repeating: 0, count: cps.count)
    var k = 0
    while k < cps.count { classes[k] = jsCombiningClass(cps[k]); k += 1 }
    var start = 0
    while start < cps.count {
        if classes[start] == 0 { start += 1; continue }
        var end = start
        while end < cps.count && classes[end] != 0 { end += 1 }
        if end - start > 1 {
            // Insertion sort (runs are short in practice; cap the quadratic cost by a merge-free shell).
            var a = start + 1
            if end - start > 64 {
                // Longer runs: counting sort by class (stable).
                var buckets = [[UInt32]](repeating: [], count: 256)
                var b = start
                while b < end { buckets[Int(classes[b])].append(cps[b]); b += 1 }
                var w = start
                for cls in 0..<256 {
                    for c in buckets[cls] { cps[w] = c; classes[w] = UInt8(cls); w += 1 }
                }
            } else {
                while a < end {
                    let c = cps[a], cl = classes[a]
                    var b = a
                    while b > start && classes[b - 1] > cl {
                        cps[b] = cps[b - 1]; classes[b] = classes[b - 1]
                        b -= 1
                    }
                    cps[b] = c; classes[b] = cl
                    a += 1
                }
            }
        }
        start = end
    }
    if form == .nfc || form == .nfkc {
        // Compose.
        if !cps.isEmpty {
            var starterPos = 0
            var starter = cps[0]
            var lastClass: Int = Int(classes[0])
            if lastClass != 0 { lastClass = 256 }
            var comp = 1
            var d = 1
            while d < cps.count {
                let ch = cps[d]
                let chClass = Int(classes[d])
                if let composite = jsComposePair(starter, ch), lastClass < chClass || lastClass == 0 {
                    cps[starterPos] = composite
                    starter = composite
                } else {
                    if chClass == 0 { starterPos = comp; starter = ch }
                    lastClass = chClass
                    cps[comp] = ch
                    comp += 1
                }
                d += 1
            }
            cps.removeSubrange(comp..<cps.count)
        }
    }
    var out: [UInt16] = []
    out.reserveCapacity(cps.count)
    for c in cps { jsAppendCodePoint(&out, c) }
    return out
}
